--- 685/nes_native_runtime165.c
+++ 686/nes_native_runtime165.c
@@ -27,10 +27,8 @@
  struct nes_native_runtime165 *s=ctx;
  if(!guard(s))return false;
  s->inside_transfer=true;unsigned opcode=tx[0];
- bool seal=opcode==0xe1&&n>=2&&tx[1]==3;
  bool ok=s->transfer(s->ctx,tx,rx,n);
  s->inside_transfer=false;
- if(ok&&seal&&s->receiver->state==NES_NATIVE165_COMMITTED)s->prefetch_left=7;
  s->transactions++;s->wire_bytes+=n;
  nes_budget210_wire(opcode,n,ok);
  if(!ok)return fail(s,NES_RUNTIME165_IO);
--- 685/nes_sink_window184.c
+++ 686/nes_sink_window184.c
@@ -102,5 +102,10 @@
   * A section-5 tail may precede SEAL in FIFO order. The post-send barrier
   * still requires the complete final display ACK; guard and credit run in send. */
  if(s->ever_sent && (p[0]!=3 || s->last[1]!=5) && !nes_window184_drain(s,ack))return false;
- return send(s,p,n)&&nes_window184_drain(s,ack);
+ /* The completed SEAL transaction owns no further output payload.
+  * Borrow input SPI before the first E0, then require the unchanged complete
+  * final identity. Failed send/STOP never enter input; input never commits. */
+ if(!send(s,p,n))return false;
+ if(p[0]==3 && !wait474(s,3,false))return false;
+ return nes_window184_drain(s,ack);
 }
